function validateCustodyChain(build, errors) {
  if (!Array.isArray(build.custody_chain) || build.custody_chain.length !== 5) {
    errors.push('PC-56 custody chain must contain five events');
    return;
  }
  if (build.custody_chain.some(event => !record(event))) {
    errors.push('PC-56 custody events must be objects');
    return;
  }
  let previous = null;
  for (const [index, event] of build.custody_chain.entries()) {
    if (event.event_index !== index + 1) {
      errors.push(`PC-56 custody event ${index} index mismatch`);
    }
    if (event.previous_event_sha256 !== previous) {
      errors.push(`PC-56 custody event ${index} previous hash mismatch`);
    }
    const { event_sha256, ...unsigned } = event;
    if (event_sha256 !== sha256(unsigned)) {
      errors.push(`PC-56 custody event ${index} hash mismatch`);
    }
    previous = event_sha256;
  }
  if (build.custody_chain_head_sha256 !== previous) {
    errors.push('PC-56 custody chain head mismatch');
  }
}

export function validatePreferenceLinkageRepositoryOwnerImmutableRepositoryIdTransferRenameForkNetworkCanonicalLocationAssuranceBuild(build, fixture) {
  const errors = [];
  validateCanonicalJsonTree(build, 'PC-56 build', errors);
  if (errors.length) return unique(errors);
  if (!record(build)) return ['PC-56 build must be an object'];

  requireExactKeys(build, BUILD_KEYS, 'PC-56 build', errors);
  for (const field of ['worlds','required_refusal_rules','custody_chain']) {
    if (!Array.isArray(build[field])) errors.push(`PC-56 build ${field} must be an array`);
  }
  for (const field of ['baseline','metrics','classification','interpretation_contract']) {
    if (!record(build[field])) errors.push(`PC-56 build ${field} must be an object`);
  }
  if (Array.isArray(build.worlds) && build.worlds.some(world => !record(world))) {
    errors.push('PC-56 compiled worlds must be objects');
  }
  if (errors.length) return unique(errors);

  for (const world of build.worlds) {
    requireExactKeys(world, COMPILED_WORLD_KEYS, `PC-56 compiled world ${world.world_id}`, errors);
  }

  const fixtureErrors = validatePreferenceLinkageRepositoryOwnerImmutableRepositoryIdTransferRenameForkNetworkCanonicalLocationAssuranceFixture(fixture);
  errors.push(...fixtureErrors);
  if (fixtureErrors.length) return unique(errors);

  let expected;
  try {
    expected = compilePreferenceLinkageRepositoryOwnerImmutableRepositoryIdTransferRenameForkNetworkCanonicalLocationAssuranceFixture(fixture);
  } catch (error) {
    return [`PC-56 deterministic compile failed: ${error.message}`];
  }

  if (stable(build) !== stable(expected)) {
    errors.push('PC-56 build differs from deterministic compilation');
  }
  if (
    stable(build.metrics) !==
    stable(EXPECTED_LINKAGE_REPOSITORY_OWNER_ID_LOCATION_FORK_TRANSFER_RENAME_ASSURANCE_METRICS)
  ) {
    errors.push('PC-56 metrics mismatch');
  }
  if (
    build.world_count !== 8 ||
    build.complete_assurance_world_count !== 1 ||
    build.public_signature_count !== 1 ||
    build.identity_governance_signature_count !== 8
  ) {
    errors.push('PC-56 build denominator mismatch');
  }
  if (
    stable(build.classification) !== stable(EXPECTED_FIXTURE_LITERAL.expected_classification)
  ) {
    errors.push('PC-56 build classification mismatch');
  }
  validateCustodyChain(build, errors);
  return unique(errors);
}

